// blob.h
typedef struct { size_t len; unsigned char* data; } Blob;
Blob* gen_blob(int seed, size_t n);
void blob_free(Blob* b);
```
```go
// blob.go
/*
#include "blob.h"
*/
import "C"
import "unsafe"
import "fmt"
func MakeBlob(n int) ([]byte, error) {
  b := C.gen_blob(0, C.size_t(n))
  if b == nil { return nil, fmt.Errorf("C gen_blob failed") }
  data := C.GoBytes(unsafe.Pointer(b.data), C.int(b.len))
  C.blob_free(b)
  return data, nil
}
```

